// Typed access to data generated by scripts/migrate-legacy.mjs.
import menus from './legacy/menus.json';
import documents from './legacy/documents.json';
import disclosures from './legacy/disclosures.json';

export interface MenuLink {
  label: string;
  href: string | null;
  children?: MenuLink[];
}
export interface LegacyDocument {
  title: string;
  path: string;
  legacyUrl: string;
  campus: string | null;
  category: string;
  bytes?: number;
}

/** A campus's menu groups (About, Parent Resources, Programs, Portals, …), minus links that go nowhere. */
export function campusMenu(slug: string): MenuLink[] {
  const groups = (menus.campuses as Record<string, MenuLink[]>)[slug] ?? [];
  return groups
    .map((g) => ({ ...g, children: g.children?.filter((c) => c.href) }))
    .filter((g) => g.href || g.children?.length);
}

/** Find a link in a campus menu by label pattern, e.g. /lunch/i. */
export function findCampusLink(slug: string, pattern: RegExp): string | undefined {
  for (const g of campusMenu(slug)) {
    if (pattern.test(g.label) && g.href) return g.href;
    const hit = g.children?.find((c) => pattern.test(c.label));
    if (hit?.href) return hit.href;
  }
}

/** Breakfast/lunch menu links for a campus; one combined link when both point at the same PDF. */
export function mealMenuLinks(slug: string): { label: string; href: string }[] {
  const breakfast = findCampusLink(slug, /breakfast/i);
  const lunch = findCampusLink(slug, /lunch/i);
  if (breakfast && breakfast === lunch) return [{ label: 'Breakfast & lunch menu', href: breakfast }];
  return [
    ...(breakfast ? [{ label: 'Breakfast menu', href: breakfast }] : []),
    ...(lunch ? [{ label: 'Lunch menu', href: lunch }] : []),
  ];
}

export const legacyDocuments = documents as LegacyDocument[];
export const salaryDisclosure = (slug: string) => (disclosures as Record<string, string>)[slug];
